def predict(board, action):
    row, col = action
    action_char = 'p'
    new_board = [list(row) for row in board]

    for i in range(max(0, row-1), min(63, row+2)):
        for j in range(max(0, col-1), min(63, col+2)):
            if new_board[i][j] == 'W':
                new_board[i][j] = action_char

    new_board[row][col] = 'S'
    return [''.join(row) for row in new_board]
